import { Slide } from '../slider';
import { Sprite, Texture, Container, Text, TextStyleOptions } from 'pixi.js';
import { IInfoPopupSlideStrings, IInstructionSlideConfig } from './instruction-slide';

export interface ISymbolDetailTextStyles {
    default: TextStyleOptions;
    title: TextStyleOptions;
    highlight?: TextStyleOptions;
}

export interface ISymbolDetailSlideConfig extends IInstructionSlideConfig {
    leftImageWidth?: number;
    rightImageWidth?: number;
    rightImagePadding?: {top?: number, bottom?: number};
    fontStyles: ISymbolDetailTextStyles;
}

export class SymbolDetailSlide extends Slide {
    protected leftImage: Sprite;
    protected rightImage: Sprite;
    protected symbolDetailSlideConfig: ISymbolDetailSlideConfig;
    
    private screenText: Container;
    private strings: (IInfoPopupSlideStrings | null)[];
    
    private leftTitleText!: Text;
    private leftTextPoints: Text[] = [];
    private rightTitleText!: Text;
    private rightTextPoints: Text[] = [];
    
    constructor(imageTextures: Texture[], strings: (IInfoPopupSlideStrings | null)[], config: ISymbolDetailSlideConfig) {
        super();

        this.strings = strings;
        this.symbolDetailSlideConfig = config;

        this.leftImage = new Sprite(imageTextures[0]);
        this.leftImage.anchor.set(0.5, 0);
        this.addChild(this.leftImage);

        this.rightImage = new Sprite(imageTextures[1]);
        this.addChild(this.rightImage);

        this.screenText = new Container();
        this.addChild(this.screenText);

        this.createTextSections(config.fontStyles);
    }

    public resize(width: number, height: number, offset: { x: number; y: number; }): void {
        super.resize(width, height, offset);

        const leftImageArea = width * (this.symbolDetailSlideConfig?.leftImageWidth ?? 0.55);
        const leftWidthScale = leftImageArea / this.leftImage.texture.width;
        const leftHeightScale = height / this.leftImage.texture.height;
        const leftScale = Math.min(leftWidthScale, leftHeightScale);

        this.leftImage.scale.set(leftScale);
        this.leftImage.x = -width * 0.25;
        this.leftImage.y = -(height * 0.5);

        const rightImageArea = width * (this.symbolDetailSlideConfig?.rightImageWidth ?? 0.55);
        const widthScale = rightImageArea / this.rightImage.texture.width;
        const heightScale = height / this.rightImage.texture.height;
        const scale = Math.min(widthScale, heightScale);

        if (this.strings[0]) {
            let initialPointYPosition: number = this.leftImage.y + this.leftImage.height;

            if (this.leftTitleText !== undefined) {
                this.leftTitleText.x = -width * 0.25;
                this.leftTitleText.y = initialPointYPosition;
                initialPointYPosition = this.leftTitleText.y + this.leftTitleText.height;
            }

            this.leftTextPoints.forEach((point: Text, index: number, array: Text[]) => {
                const yOffset = index === 0 ? initialPointYPosition : array[index - 1].y + array[index - 1].height;

                point.style.wordWrapWidth = width * 0.48;
                point.x = -width * 0.25;
                point.y = yOffset;
            });
        }

        this.rightImage.scale.set(scale);
        this.rightImage.x = width * 0.25;
        this.rightImage.y = height * 0.5;
        this.rightImage.anchor.set(0.5);

        if (this.strings[1]) {
            this.rightTitleText.x = width * 0.25;
            this.rightTitleText.y = -(height * 0.5);

            this.rightImage.anchor.set(0.5, 0);
            this.rightImage.y = this.rightTitleText.y + this.rightTitleText.height + (this.symbolDetailSlideConfig?.rightImagePadding?.top ?? 0);

            this.rightTextPoints.forEach((point: Text, index: number, array: Text[]) => {
                const yOffset = index === 0 ? this.rightImage.y + this.rightImage.height + (this.symbolDetailSlideConfig?.rightImagePadding?.bottom ?? 0) : array[index - 1].y + array[index - 1].height;
                point.style.wordWrapWidth = width * 0.48;
                point.x = width * 0.25;
                point.y = yOffset;
            });
        }
    }

    private createTextSections(textStyles: ISymbolDetailTextStyles): void {
        if (this.strings[0]) {
            if (this.strings[0].title !== '') {
                this.leftTitleText = new Text({ text: this.strings[0].title, style: textStyles?.title });
                this.leftTitleText.anchor.set(0.5, 0);
                this.screenText.addChild(this.leftTitleText);
            }

            this.strings[0].points?.forEach((point: string) => {
                const newPoint = new Text({ text: point, style: textStyles.default });
                newPoint.anchor.set(0.5, 0);

                this.leftTextPoints.push(newPoint);
                this.screenText.addChild(newPoint);
            });
        }

        if (this.strings[1]) {
            this.rightTitleText = new Text({ text: this.strings[1].title, style: textStyles?.title });
            this.rightTitleText.anchor.set(0.5, 0);
            this.screenText.addChild(this.rightTitleText);

            this.strings[1].points?.forEach((point: string) => {
                const newPoint = new Text({ text: point, style: textStyles?.default });
                newPoint.anchor.set(0.5, 0);

                this.rightTextPoints.push(newPoint);
                this.screenText.addChild(newPoint);
            });
        }
    }
}